<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import QRCode from 'qrcode'
import { api } from './api/client'
import type { Asset, Profile, Wallet, Tx, Quote } from './api/types'
import { formatAmount } from './lib/amount'
const router=useRouter(),route=useRoute();const locked=ref(true),profile=ref<Profile>('test'),wallets=ref<Wallet[]>([]),selected=ref(''),page=ref('home'),password=ref(''),error=ref(''),busy=ref(false),history=ref<Tx[]>([]),filter=ref<Asset|'ALL'>('ALL'),asset=ref<Asset>('BTC'),recipient=ref(''),amount=ref(''),quote=ref<Quote>(),passphrase=ref(''),name=ref('Новый кошелёк'),seed=ref(''),mode=ref<'create'|'import'>('create'),step=ref(1),qr=ref(''),address=ref(''),timeout=ref(5),newName=ref(''),notice=ref('');const current=computed(()=>wallets.value.find(w=>w.id===selected.value));const assets:Asset[]=['BTC','ETH','USDC','USDT'];const generated='abandon ability able about above absent absorb abstract absurd abuse access accident',seedVisible=ref(false)
const clipboard=navigator.clipboard
watch(page,p=>{const path=p==='home'?'/':'/'+p;if(route.path!==path)void router.replace(path)})
watch(()=>route.path,p=>{const next=p==='/'?'home':p.slice(1);if(next&&next!==page.value)page.value=next})
watch(page,(next,previous)=>{if(previous==='wizard'&&next!=='wizard'){seed.value='';seedVisible.value=false;password.value='';passphrase.value=''}if(['send','review','confirm'].includes(previous)&&!['send','review','confirm'].includes(next)){password.value='';passphrase.value=''}})
async function refresh(){try{const s=await api.session();locked.value=s.locked;profile.value=s.profile;timeout.value=s.timeout;if(!s.locked){wallets.value=await api.wallets();if(!selected.value&&wallets.value[0])selected.value=wallets.value[0].id}}catch(e){error.value=String(e)}}
async function unlock(){busy.value=true;error.value='';try{await api.unlock(password.value);password.value='';await refresh();page.value='home'}catch{error.value='Не удалось разблокировать. Проверьте пароль.';password.value=''}finally{busy.value=false}}
async function lock(){await api.lock();locked.value=true;wallets.value=[];password.value='';seed.value='';passphrase.value='';page.value='lock'}
async function loadHistory(){if(selected.value)history.value=await api.history(selected.value,filter.value==='ALL'?undefined:filter.value)}
async function showReceive(a:Asset){asset.value=a;address.value=await api.receive(selected.value,a);qr.value=await QRCode.toDataURL(address.value,{width:220,margin:1});page.value='receive'}
async function createWallet(){error.value='';if(!name.value.trim()||password.value.length<10){error.value='Название обязательно, пароль — не менее 10 символов.';return}if(mode.value==='import'&&![12,24].includes(seed.value.trim().split(/\s+/).length)){error.value='Введите seed из 12 или 24 слов';return}if(import.meta.env.VITE_WALLET_API==='wails'){error.value='Мастер создания и импорта ожидает согласования DTO и методов Dev 7. Секреты не отправляются через неподтверждённый контракт.';return}busy.value=true;try{const w=await api.create(name.value,mode.value==='create'?generated:seed.value,password.value,passphrase.value);wallets.value.push(w);selected.value=w.id;name.value='';seed.value='';password.value='';passphrase.value='';page.value='home'}catch{error.value='Не удалось создать кошелёк.'}finally{busy.value=false}}
async function prepare(){error.value='';busy.value=true;try{quote.value=await api.prepare(selected.value,asset.value,recipient.value,amount.value);page.value='review'}catch{error.value='Проверьте адрес и сумму.'}finally{busy.value=false}}
async function send(){if(!quote.value)return;busy.value=true;try{await api.confirm(quote.value.draftId,password.value,passphrase.value);password.value='';passphrase.value='';await loadHistory();page.value='history'}catch{error.value='Операция не подтверждена.';password.value='';passphrase.value=''}finally{busy.value=false}}
async function setProfile(p:Profile){await api.profile(p);profile.value=p}async function rename(){if(current.value&&newName.value.trim()){await api.rename(selected.value,newName.value.trim());await refresh();notice.value='Название сохранено'}}async function backup(){try{await api.backup(password.value);notice.value='Запрос резервной копии выполнен'}catch{notice.value='Не удалось создать резервную копию'}finally{password.value=''}}async function copyAddress(){await clipboard.writeText(address.value)}
onMounted(refresh);onBeforeUnmount(()=>{password.value='';passphrase.value='';seed.value=''})
</script>
<template><main v-if="locked" class="lock"><section class="card lock-card"><div class="logo">W</div><p class="muted">ЛОКАЛЬНЫЙ НЕКАСТОДИАЛЬНЫЙ КОШЕЛЁК</p><h1>Кошелёк заблокирован</h1><form @submit.prevent="unlock"><label>Пароль</label><input v-model="password" type="password" autocomplete="off" autofocus required><p v-if="error" class="error">{{error}}</p><button class="primary" :disabled="busy">Разблокировать</button></form><span class="badge">ТЕСТОВАЯ СЕТЬ</span></section></main><div v-else class="layout"><aside><div class="brand"><b>W</b> Wallet</div><span class="badge" :class="{main:profile==='main'}">{{profile==='test'?'ТЕСТОВАЯ СЕТЬ':'MAINNET'}}</span><nav><button @click="page='home'">⌂ Обзор</button><button @click="page='wizard';step=1">＋ Добавить кошелёк</button><button @click="page='history';loadHistory()">↔ История</button><button @click="page='settings'">⚙ Настройки</button></nav><button class="quiet" @click="lock">Заблокировать ↪</button></aside><main class="content"><header><div><small>NON-CUSTODIAL DESKTOP WALLET</small><h1>{{page==='home'?'Ваши активы':page==='wizard'?'Добавить кошелёк':page==='receive'?'Получение':page==='send'||page==='review'||page==='confirm'?'Отправка':page==='history'?'История операций':page==='settings'?'Настройки':'Кошелёк'}}</h1></div><span class="network">{{profile==='test'?'Bitcoin testnet · Sepolia · Nile':'Bitcoin · Ethereum · TRON'}}</span></header>
<section v-if="page==='home'" class="stack"><div class="heading"><div><h2>Кошельки</h2><p class="muted">Баланс и обновление по каждому активу</p></div><button class="primary" @click="page='wizard';step=1">＋ Добавить</button></div><article v-for="w in wallets" :key="w.id" class="card"><div class="heading"><h3>{{w.name}}</h3><button class="quiet" @click="selected=w.id;page='wallet'">Открыть →</button></div><div class="assets"><div v-for="b in w.balances" :key="b.asset" class="asset"><small>{{b.network}}</small><b>{{b.asset}}</b><strong>{{formatAmount(b.amount,b.decimals)}} <small>{{b.asset}}</small></strong><small class="muted">Обновлено {{new Date(b.updatedAt).toLocaleTimeString('ru-RU')}}</small><button class="secondary" @click="selected=w.id;showReceive(b.asset)">Получить</button></div></div></article><div v-if="!wallets.length" class="card empty">Кошельков пока нет. Создайте или импортируйте seed.</div></section>
<section v-else-if="page==='wizard'" class="stack narrow"><div class="steps">Шаг {{step}} из 3</div><article class="card stack"><template v-if="step===1"><h2>Как добавить кошелёк?</h2><div class="row"><button :class="{selected:mode==='create'}" @click="mode='create'">Создать новый</button><button :class="{selected:mode==='import'}" @click="mode='import'">Импортировать</button></div><label>Название</label><input v-model="name" autocomplete="off"><button class="primary" @click="step=2">Продолжить</button></template><template v-else-if="step===2"><h2>{{mode==='create'?'Seed-фраза':'Импорт seed'}}</h2><p class="warning">Никому не сообщайте seed-фразу. Она даёт полный доступ к средствам.</p><template v-if="mode==='create'"><p v-if="seedVisible" class="seed">{{generated}}</p><button class="secondary" @click="seedVisible=!seedVisible">{{seedVisible?'Скрыть фразу':'Показать seed-фразу'}}</button></template><textarea v-else v-model="seed" rows="4" autocomplete="off" placeholder="Введите 12 или 24 слова"></textarea><p class="muted">Демонстрационная фраза работает только в мок-режиме. Реальный генератор подключается через Go DTO.</p><button class="primary" @click="step=3">Я записал фразу</button></template><template v-else><h2>Защитите кошелёк</h2><label>Пароль (минимум 10 символов)</label><input v-model="password" type="password" autocomplete="off"><label>Парольная фраза BIP39 (необязательно)</label><input v-model="passphrase" type="password" autocomplete="off"><p v-if="error" class="error">{{error}}</p><button class="primary" :disabled="busy" @click="createWallet">Сохранить кошелёк</button></template><button class="quiet" @click="step=Math.max(1,step-1)">← Назад</button></article></section>
<section v-else-if="page==='wallet'" class="stack"><div class="heading"><h2>{{current?.name}}</h2><button class="primary" @click="page='send'">Отправить</button></div><div class="assets"><article v-for="b in current?.balances" :key="b.asset" class="card asset"><small>{{b.network}}</small><h3>{{b.asset}}</h3><strong>{{formatAmount(b.amount,b.decimals)}} {{b.asset}}</strong><button class="secondary" @click="showReceive(b.asset)">Получить {{b.asset}}</button></article></div></section>
<section v-else-if="page==='receive'" class="card narrow stack"><h2>Получить {{asset}}</h2><p class="warning">Принимайте только {{asset}} в правильной сети.</p><span class="network">{{asset==='BTC'?'Bitcoin testnet':asset==='USDT'?'TRON Nile':'Ethereum Sepolia'}}</span><img v-if="qr" :src="qr" class="qr" alt="QR-код адреса"><code class="seed">{{address}}</code><button class="primary" @click="copyAddress">Скопировать адрес</button><button class="quiet" @click="page='wallet'">Назад</button></section>
<section v-else-if="page==='send'" class="card narrow stack"><h2>Новый перевод</h2><label>Актив</label><select v-model="asset"><option v-for="a in assets" :key="a">{{a}}</option></select><label>Адрес получателя</label><input v-model="recipient" autocomplete="off" spellcheck="false"><label>Сумма</label><input v-model="amount" inputmode="decimal" autocomplete="off"><p v-if="error" class="error">{{error}}</p><button class="primary" :disabled="busy" @click="prepare">Проверить перевод</button></section>
<section v-else-if="page==='review'&&quote" class="card narrow stack"><h2>Проверьте перевод</h2><dl><dt>Сеть</dt><dd>{{quote.network}}</dd><dt>Актив</dt><dd>{{quote.asset}}</dd><dt>Получатель</dt><dd class="break">{{quote.recipient}}</dd><dt>Сумма</dt><dd>{{quote.amount}} {{quote.asset}}</dd><dt>Комиссия</dt><dd>{{quote.fee}} {{quote.feeAsset}}</dd></dl><p v-for="w in quote.warnings" :key="w" class="warning">{{w}}</p><button class="primary" @click="page='confirm'">Далее</button></section>
<section v-else-if="page==='confirm'" class="card narrow stack"><h2>Подтверждение</h2><label>Пароль</label><input v-model="password" type="password" autocomplete="off"><label>Парольная фраза BIP39</label><input v-model="passphrase" type="password" autocomplete="off"><p class="warning">Go повторно проверяет намерение, комиссию и подпись.</p><p v-if="error" class="error">{{error}}</p><button class="primary" :disabled="busy" @click="send">Подписать и отправить</button></section>
<section v-else-if="page==='history'" class="stack"><div class="heading"><h2>История</h2><select v-model="filter" @change="loadHistory"><option value="ALL">Все активы</option><option v-for="a in assets" :key="a">{{a}}</option></select></div><article class="card"><p v-if="!history.length" class="muted">Операций пока нет.</p><div v-for="tx in history" :key="tx.id" class="tx"><b>{{tx.asset}} · {{tx.direction==='in'?'Входящая':'Исходящая'}}</b><span>{{tx.amount}} · {{tx.status}}</span><small>{{tx.address}}</small></div></article></section>
<section v-else-if="page==='settings'" class="stack narrow"><article class="card stack"><h2>Профиль сети</h2><div class="row"><button :class="{selected:profile==='test'}" @click="setProfile('test')">Тестовые сети</button><button :class="{selected:profile==='main'}" @click="setProfile('main')">Основные сети</button></div><p v-if="profile==='test'" class="warning">Bitcoin testnet · Ethereum Sepolia · TRON Nile</p></article><article class="card stack"><h2>Автоблокировка</h2><select v-model.number="timeout" @change="api.timeout(timeout)"><option :value="1">1 минута</option><option :value="5">5 минут</option><option :value="10">10 минут</option><option :value="15">15 минут</option><option :value="30">30 минут</option></select></article><article class="card stack"><h2>Управление кошельком</h2><input v-model="newName" placeholder="Новое название"><button class="secondary" @click="rename">Переименовать выбранный</button><label>Пароль для резервной копии</label><input v-model="password" type="password" autocomplete="off"><button class="secondary" @click="backup">Создать резервную копию</button><p>{{notice}}</p></article></section>
</main></div></template>
